import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const DEFAULT_PATH = join(process.cwd(), 'data', 'books.json');

function nowIso() {
  return new Date().toISOString();
}

export function generateId() {
  return randomBytes(4).toString('hex');
}

export function loadBooks(filePath = DEFAULT_PATH) {
  if (!existsSync(filePath)) return [];
  const raw = readFileSync(filePath, 'utf8');
  if (!raw.trim()) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function saveBooks(books, filePath = DEFAULT_PATH) {
  const tmp = `${filePath}.tmp`;
  writeFileSync(tmp, JSON.stringify(books, null, 2));
  renameSync(tmp, filePath);
}

export function addBook({ title, author }, filePath = DEFAULT_PATH) {
  const book = {
    id: generateId(),
    title: title.trim(),
    author: author.trim(),
    status: 'reading',
    notes: '',
    addedAt: nowIso(),
    finishedAt: null,
  };
  const books = loadBooks(filePath);
  books.push(book);
  saveBooks(books, filePath);
  return book;
}

export function findBook(id, filePath = DEFAULT_PATH) {
  return loadBooks(filePath).find((b) => b.id === id) ?? null;
}

export function updateBook(id, patch, filePath = DEFAULT_PATH) {
  const books = loadBooks(filePath);
  const idx = books.findIndex((b) => b.id === id);
  if (idx === -1) return null;
  books[idx] = { ...books[idx], ...patch };
  saveBooks(books, filePath);
  return books[idx];
}

export function finishBook(id, filePath = DEFAULT_PATH) {
  return updateBook(id, { status: 'finished', finishedAt: nowIso() }, filePath);
}

export function setNotes(id, notes, filePath = DEFAULT_PATH) {
  return updateBook(id, { notes }, filePath);
}

