import { escapeHtml, formatDate } from './util.js';

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>${escapeHtml(title)} · Books</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  :root {
    --bg: #fafaf7;
    --fg: #1a1a1a;
    --muted: #6b6359;
    --accent: #6a533b;
    --line: #e8e3d8;
    --soft: #f1ede4;
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #1c1b18;
      --fg: #ece7dc;
      --muted: #9a938a;
      --accent: #d8b88a;
      --line: #2e2c27;
      --soft: #25231e;
    }
  }
  * { box-sizing: border-box; }
  body {
    font-family: Georgia, "Iowan Old Style", "Times New Roman", serif;
    max-width: 38rem;
    margin: 2.5rem auto;
    padding: 0 1.25rem 4rem;
    line-height: 1.55;
    background: var(--bg);
    color: var(--fg);
  }
  a { color: var(--accent); text-decoration: none; }
  a:hover { text-decoration: underline; }
  h1 { font-size: 1.8rem; margin: 0; font-weight: 700; }
  h2 {
    font-size: 0.78rem;
    margin: 2.2rem 0 0.5rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
  }
  ul.books { list-style: none; padding: 0; margin: 0; border-top: 1px solid var(--line); }
  ul.books li {
    padding: 0.7rem 0;
    border-bottom: 1px solid var(--line);
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    flex-wrap: wrap;
  }
  ul.books .title { font-weight: 600; }
  ul.books .author { color: var(--muted); font-size: 0.95rem; }
  ul.books .actions { margin-left: auto; display: flex; gap: 0.6rem; }
  ul.books form { display: inline; margin: 0; }
  .empty { color: var(--muted); font-style: italic; padding: 0.4rem 0; }
  form.add, form.notes { margin: 1.5rem 0; display: grid; gap: 0.7rem; }
  label { font-size: 0.85rem; color: var(--muted); display: block; margin-bottom: 0.25rem; }
  input[type=text], textarea {
    width: 100%;
    padding: 0.55rem 0.65rem;
    border: 1px solid var(--line);
    border-radius: 4px;
    background: var(--soft);
    color: var(--fg);
    font: inherit;
  }
  input[type=text]:focus, textarea:focus {
    outline: 2px solid var(--accent);
    outline-offset: 1px;
  }
  textarea { min-height: 8rem; resize: vertical; font-family: inherit; }
  button {
    background: var(--accent);
    color: var(--bg);
    border: 0;
    border-radius: 4px;
    padding: 0.55rem 0.95rem;
    font: inherit;
    cursor: pointer;
  }
  button.ghost {
    background: transparent;
    color: var(--accent);
    border: 1px solid var(--line);
    padding: 0.3rem 0.65rem;
    font-size: 0.85rem;
  }
  button:hover { filter: brightness(1.08); }
  .meta { color: var(--muted); font-size: 0.9rem; margin: 0.25rem 0 1.5rem; }
  .notes-block {
    white-space: pre-wrap;
    background: var(--soft);
    padding: 0.9rem 1rem;
    border-radius: 4px;
    border: 1px solid var(--line);
  }
  .top {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 0.5rem;
  }
  .error { color: #b14a4a; margin: 0.5rem 0 1rem; }
  footer {
    margin-top: 3rem;
    color: var(--muted);
    font-size: 0.8rem;
    text-align: center;
  }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookRow(book, showFinish) {
  const finishBtn = showFinish
    ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button type="submit" class="ghost">Mark finished</button></form>`
    : '';
  return `<li>
  <a class="title" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
  <span class="author">by ${escapeHtml(book.author)}</span>
  <span class="actions">${finishBtn}</span>
</li>`;
}

export function homePage(books) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');

  const readingBlock = reading.length
    ? `<ul class="books">${reading.map((b) => bookRow(b, true)).join('')}</ul>`
    : `<p class="empty">No books in progress. <a href="/books/new">Add one</a>.</p>`;

  const finishedBlock = finished.length
    ? `<ul class="books">${finished.map((b) => bookRow(b, false)).join('')}</ul>`
    : `<p class="empty">Nothing finished yet.</p>`;

  const body = `
<div class="top">
  <h1>My Books</h1>
  <a href="/books/new">+ Add a book</a>
</div>
<h2>Currently reading · ${reading.length}</h2>
${readingBlock}
<h2>Finished · ${finished.length}</h2>
${finishedBlock}
<footer>Stored locally in <code>data/books.json</code>.</footer>
`;

  return layout('Home', body);
}

export function newBookForm(error) {
  const err = error ? `<p class="error">${escapeHtml(error)}</p>` : '';
  const body = `
<div class="top">
  <h1>Add a book</h1>
  <a href="/">← Back</a>
</div>
${err}
<form class="add" method="post" action="/books">
  <div>
    <label for="title">Title</label>
    <input id="title" name="title" type="text" required autofocus>
  </div>
  <div>
    <label for="author">Author</label>
    <input id="author" name="author" type="text" required>
  </div>
  <div>
    <button type="submit">Add to reading</button>
  </div>
</form>
`;
  return layout('Add a book', body);
}

export function bookDetailPage(book, shareUrl) {
  const status = book.status === 'finished'
    ? `Finished on ${formatDate(book.finishedAt)}`
    : 'Currently reading';
  const notesContent = book.notes
    ? `<div class="notes-block">${escapeHtml(book.notes)}</div>`
    : `<p class="empty">No notes yet.</p>`;
  const finishedBtn = book.status === 'reading'
    ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish" style="display:inline; margin-left:0.5rem;"><button type="submit" class="ghost">Mark finished</button></form>`
    : '';
  const body = `
<div class="top">
  <h1>${escapeHtml(book.title)}</h1>
  <a href="/">← All books</a>
</div>
<p class="meta">by ${escapeHtml(book.author)} · ${status}${finishedBtn}</p>

<h2>Notes</h2>
${notesContent}

<form class="notes" method="post" action="/books/${encodeURIComponent(book.id)}/notes">
  <div>
    <label for="notes">Edit notes</label>
    <textarea id="notes" name="notes" placeholder="Thoughts, quotes, page numbers…">${escapeHtml(book.notes ?? '')}</textarea>
  </div>
  <div>
    <button type="submit">Save notes</button>
  </div>
</form>

<h2>Share</h2>
<p class="meta">Send someone this link to show them this book:<br>
<code>${escapeHtml(shareUrl)}</code></p>
`;
  return layout(book.title, body);
}

export function notFoundPage() {
  return layout('Not found', `
<div class="top"><h1>Not found</h1><a href="/">← Home</a></div>
<p>That book doesn't exist.</p>
`);
}

