import { createServer } from 'node:http';
import { fileURLToPath } from 'node:url';
import {
  addBook,
  findBook,
  finishBook,
  loadBooks,
  setNotes,
} from './db.js';
import { parseForm, readBody } from './util.js';
import {
  bookDetailPage,
  homePage,
  newBookForm,
  notFoundPage,
} from './views.js';

const PORT = Number(process.env.PORT) || 3000;
const HOST = process.env.HOST || '127.0.0.1';
const ID_RE = /^[a-f0-9]{8}$/;

export async function handle(req, res, { host } = {}) {
  const url = new URL(req.url, `http://${req.headers.host ?? host ?? 'localhost'}`);
  const path = url.pathname;
  const method = req.method ?? 'GET';

  if (method === 'GET' && path === '/') {
    return send(res, 200, homePage(loadBooks()));
  }

  if (method === 'GET' && path === '/books/new') {
    return send(res, 200, newBookForm());
  }

  if (method === 'POST' && path === '/books') {
    const form = parseForm(await readBody(req));
    const title = (form.title ?? '').trim();
    const author = (form.author ?? '').trim();
    if (!title || !author) {
      return send(res, 400, newBookForm('Both title and author are required.'));
    }
    const book = addBook({ title, author });
    return redirect(res, `/books/${book.id}`);
  }

  const detail = path.match(/^\/books\/([a-f0-9]+)$/);
  if (detail && method === 'GET') {
    const book = findBook(detail[1]);
    if (!book) return send(res, 404, notFoundPage());
    const shareUrl = `${url.protocol}//${url.host}/books/${book.id}`;
    return send(res, 200, bookDetailPage(book, shareUrl));
  }

  const finish = path.match(/^\/books\/([a-f0-9]+)\/finish$/);
  if (finish && method === 'POST') {
    const book = finishBook(finish[1]);
    if (!book) return send(res, 404, notFoundPage());
    return redirect(res, `/books/${finish[1]}`);
  }

  const notes = path.match(/^\/books\/([a-f0-9]+)\/notes$/);
  if (notes && method === 'POST') {
    const form = parseForm(await readBody(req));
    const book = setNotes(notes[1], form.notes ?? '');
    if (!book) return send(res, 404, notFoundPage());
    return redirect(res, `/books/${notes[1]}`);
  }

  return send(res, 404, notFoundPage());
}

function send(res, status, body) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

export const server = createServer((req, res) => {
  handle(req, res).catch((err) => {
    console.error(err);
    if (!res.headersSent) {
      res.writeHead(500, { 'content-type': 'text/plain; charset=utf-8' });
    }
    res.end('Internal server error');
  });
});

const isMain =
  process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];

if (isMain) {
  server.listen(PORT, HOST, () => {
    console.log(`Books app running at http://${HOST}:${PORT}`);
  });
}

