import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import {
  addBook,
  findBook,
  finishBook,
  generateId,
  loadBooks,
  saveBooks,
  setNotes,
} from '../src/db.js';

let dir;
let filePath;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'books-test-'));
  filePath = join(dir, 'books.json');
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

describe('generateId', () => {
  it('returns 8-char hex strings', () => {
    for (let i = 0; i < 25; i++) {
      const id = generateId();
      expect(id).toMatch(/^[a-f0-9]{8}$/);
    }
  });

  it('produces unique ids', () => {
    const ids = new Set();
    for (let i = 0; i < 200; i++) ids.add(generateId());
    expect(ids.size).toBe(200);
  });
});

describe('loadBooks / saveBooks', () => {
  it('returns [] when file is missing', () => {
    expect(loadBooks(filePath)).toEqual([]);
  });

  it('returns [] when file is empty', () => {
    saveBooks([], filePath);
    expect(loadBooks(filePath)).toEqual([]);
  });

  it('round-trips data', () => {
    const books = [
      { id: 'aa', title: 'A', author: 'X', status: 'reading', notes: '', addedAt: 't', finishedAt: null },
    ];
    saveBooks(books, filePath);
    expect(loadBooks(filePath)).toEqual(books);
  });

  it('recovers when file holds garbage', () => {
    const { writeFileSync } = require('node:fs') as any;
  });
});

describe('addBook', () => {
  it('appends a reading book with trimmed fields and timestamps', () => {
    const book = addBook({ title: '  Dune  ', author: '  Herbert ' }, filePath);
    expect(book).toMatchObject({
      title: 'Dune',
      author: 'Herbert',
      status: 'reading',
      notes: '',
      finishedAt: null,
    });
    expect(book.id).toMatch(/^[a-f0-9]{8}$/);
    expect(typeof book.addedAt).toBe('string');
    expect(findBook(book.id, filePath)).toEqual(book);
  });
});

describe('finishBook', () => {
  it('marks a book finished and stamps finishedAt', () => {
    const book = addBook({ title: 'A', author: 'B' }, filePath);
    const finished = finishBook(book.id, filePath);
    expect(finished?.status).toBe('finished');
    expect(typeof finished?.finishedAt).toBe('string');
  });

  it('returns null for unknown id', () => {
    expect(finishBook('deadbeef', filePath)).toBeNull();
  });
});

describe('setNotes', () => {
  it('updates notes for a book', () => {
    const book = addBook({ title: 'A', author: 'B' }, filePath);
    const updated = setNotes(book.id, 'great read', filePath);
    expect(updated?.notes).toBe('great read');
  });
});

