import { EventEmitter } from 'node:events';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { PassThrough } from 'node:stream';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { handle } from '../src/server.js';

function mockReq({ method = 'GET', url = '/', body = '' } = {}) {
  const req = new PassThrough();
  req.method = method;
  req.url = url;
  req.headers = { host: 'localhost:3000' };
  if (body) process.nextTick(() => req.end(body));
  else process.nextTick(() => req.end());
  return req;
}

function mockRes() {
  const res = new PassThrough();
  const headers = {};
  res.statusCode = 0;
  res.writeHead = (status, hdrs = {}) => {
    res.statusCode = status;
    Object.assign(headers, hdrs);
  };
  res.headers = headers;
  const chunks = [];
  res.on('data', (c) => chunks.push(c));
  return new Promise((resolve) => {
    res.on('end', () =>
      resolve({ status: res.statusCode, headers, body: Buffer.concat(chunks).toString('utf8') })
    );
  });
}

async function request({ method = 'GET', url = '/', body = '' } = {}) {
  const req = mockReq({ method, url, body });
  const res = mockRes();
  await handle(req, await res);
  return res;
}

let dir;
let filePath;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'books-route-test-'));
  filePath = join(dir, 'books.json');
  process.chdir(dir);
});

afterEach(() => {
  process.chdir(join(dir, '..'));
  rmSync(dir, { recursive: true, force: true });
});

describe('GET /', () => {
  it('renders the home page with seed data', async () => {
    const res = await request({ url: '/' });
    expect(res.status).toBe(200);
    expect(res.headers['content-type']).toMatch(/text\/html/);
    expect(res.body).toMatch(/<title>Home · Books<\/title>/);
    expect(res.body).toMatch(/My Books/);
    expect(res.body).toMatch(/Currently reading/);
    expect(res.body).toMatch(/Finished/);
  });
});

describe('GET /books/new', () => {
  it('renders the add-book form', async () => {
    const res = await request({ url: '/books/new' });
    expect(res.status).toBe(200);
    expect(res.body).toMatch(/Add a book/);
    expect(res.body).toMatch(/name="title"/);
    expect(res.body).toMatch(/name="author"/);
  });
});

describe('POST /books', () => {
  it('creates a book and redirects to its detail page', async () => {
    const res = await request({
      method: 'POST',
      url: '/books',
      body: 'title=Dune&author=Frank+Herbert',
    });
    expect(res.status).toBe(303);
    expect(res.headers.location).toMatch(/^\/books\/[a-f0-9]{8}$/);
  });

  it('rejects missing fields with the form again', async () => {
    const res = await request({
      method: 'POST',
      url: '/books',
      body: 'title=Only+Title',
    });
    expect(res.status).toBe(400);
    expect(res.body).toMatch(/Both title and author are required/);
  });
});

describe('GET /books/:id', () => {
  it('renders title, author, and notes', async () => {
    const create = await request({
      method: 'POST',
      url: '/books',
      body: 'title=Dune&author=Frank+Herbert',
    });
    const id = create.headers.location.split('/').pop();
    const detail = await request({ url: `/books/${id}` });
    expect(detail.status).toBe(200);
    expect(detail.body).toMatch(/Dune/);
    expect(detail.body).toMatch(/Frank Herbert/);
    expect(detail.body).toMatch(/Notes/);
    expect(detail.body).toMatch(new RegExp(`/books/${id}`));
  });

  it('returns 404 for an unknown id', async () => {
    const res = await request({ url: '/books/deadbeef' });
    expect(res.status).toBe(404);
    expect(res.body).toMatch(/Not found/);
  });
});

describe('POST /books/:id/finish', () => {
  it('marks the book finished and redirects', async () => {
    const create = await request({
      method: 'POST',
      url: '/books',
      body: 'title=Dune&author=Frank+Herbert',
    });
    const id = create.headers.location.split('/').pop();
    const finish = await request({ method: 'POST', url: `/books/${id}/finish` });
    expect(finish.status).toBe(303);
    expect(finish.headers.location).toBe(`/books/${id}`);
    const detail = await request({ url: `/books/${id}` });
    expect(detail.body).toMatch(/Finished on/);
  });
});

describe('POST /books/:id/notes', () => {
  it('saves notes and redirects', async () => {
    const create = await request({
      method: 'POST',
      url: '/books',
      body: 'title=Dune&author=Frank+Herbert',
    });
    const id = create.headers.location.split('/').pop();
    const save = await request({
      method: 'POST',
      url: `/books/${id}/notes`,
      body: 'notes=A+masterpiece.',
    });
    expect(save.status).toBe(303);
    const detail = await request({ url: `/books/${id}` });
    expect(detail.body).toMatch(/A masterpiece\./);
  });
});

